@Composable
fun FooterSection(){
    Box(modifier = Modifier
        .fillMaxWidth()
        .maxWidth(SECTION_WIDTH.px)
        .padding(topBottom = 150.px)
        .backgroundColor(Theme.LighterGray.rgb),
        contentAlignment = Alignment.Center) {
        FooterContent()
    }
}
@Composable
fun FooterContent(){
    val breakpoint = rememberBreakpoint()

    Column(
        modifier = Modifier.fillMaxSize(if (breakpoint >= Breakpoint.MD) 100.percent else 90.percent),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Image(modifier = Modifier
            .size(100.px),
            src = Res.Image.logo,
            description = "logo description"
        )
        if (breakpoint >= Breakpoint.SM){
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.Center
            ) {
                FooterMenu()
            }
        }
        else {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                FooterMenu(row = false)
            }
        }
        SocialBar(row = true)
    }
}

@Composable
fun FooterMenu(row :Boolean = true){
    Section.values().take(6).forEach { section ->
        Link(
            modifier = NavigationItemStyle.toModifier()
                .fontFamily(FONT_FAMILY)
                .padding(right = if (row)20.px else 0.px,
                    bottom = if (row) 0.px else 20.px)
                .fontSize(14.px)
                .fontWeight(FontWeight.Normal)
                .textDecorationLine(TextDecorationLine.None),
            path = section.path,
            text = section.title
        )
    }
}
